def minimumSum(S):
    n = len(S)
    S = list(S)
    left = 0
    right = n - 1
    while left < right:
        if S[left] == '?' and S[right] == '?':
            S[left] = S[right] = 'a'
        elif S[left] == '?':
            S[left] = S[right]
        elif S[right] == '?':
            S[right] = S[left]
        elif S[left] != S[right]:
            return -1
        left += 1
        right -= 1
    result = 0
    for i in range(1, n):
        result += abs(ord(S[i]) - ord(S[i - 1]))
    return result
